'use strict';
const menu=document.querySelector('.menu-toggle'),nav=document.getElementById('mobile-nav');
function closeNav(){if(!menu||!nav)return;nav.hidden=true;menu.setAttribute('aria-expanded','false');menu.setAttribute('aria-label','Open navigation');}
menu?.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')==='true';nav.hidden=open;menu.setAttribute('aria-expanded',String(!open));menu.setAttribute('aria-label',open?'Open navigation':'Close navigation');});
nav?.querySelectorAll('a').forEach(a=>a.addEventListener('click',closeNav));
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&menu?.getAttribute('aria-expanded')==='true'){closeNav();menu.focus();}});
document.querySelectorAll('[data-year]').forEach(s=>s.textContent=new Date().getFullYear());
const year=document.getElementById('year');if(year)year.textContent=new Date().getFullYear();
if(!matchMedia('(prefers-reduced-motion: reduce)').matches&&'IntersectionObserver' in window){document.documentElement.classList.add('js-motion');const observer=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('visible');observer.unobserve(e.target);}}),{threshold:.06});document.querySelectorAll('.reveal').forEach(el=>observer.observe(el));}
const directory=document.getElementById('directory-grid');
if(directory){let selected='all';const search=document.getElementById('service-search');const filters=[...document.querySelectorAll('[data-category-filter]')];const cards=[...directory.querySelectorAll('.service-card')];function apply(){const q=search.value.trim().toLowerCase();let count=0;cards.forEach(c=>{const show=(selected==='all'||c.dataset.category===selected)&&c.textContent.toLowerCase().includes(q);c.hidden=!show;if(show)count++;});document.getElementById('result-count').textContent=`${count} ${count===1?'service':'services'}${selected==='all'?'':' in '+selected}`;document.querySelector('.no-results').hidden=count!==0;filters.forEach(f=>{const on=f.dataset.categoryFilter===selected;f.classList.toggle('selected',on);f.setAttribute('aria-pressed',String(on));});}filters.forEach(f=>f.addEventListener('click',()=>{selected=f.dataset.categoryFilter;apply();}));search.addEventListener('input',apply);const initial=new URLSearchParams(location.search).get('category');if(filters.some(f=>f.dataset.categoryFilter===initial))selected=initial;apply();}
const features=[...document.querySelectorAll('[data-view]')];
const views={projects:{title:'Your next milestone',kicker:'PROJECT TRACKER',name:'Company registration',description:'From an idea to officially in business.',badge:'In progress',progress:'66%',milestones:[['✓','Documents','done'],['✓','Name approval','done'],['3','Filing','current'],['4','Incorporation','']],bottom:'Your YBS expert is taking care of the next step.'},documents:{title:'A little input. A big step forward.',kicker:'YOUR NEXT ACTION',name:'Documents for your registration',description:'Keep your project moving with the right details.',badge:'Needs you',progress:'50%',milestones:[['✓','Identity','done'],['✓','Address','done'],['3','Business details','current'],['4','Review','']],bottom:'Your workspace keeps the next action visible.'},deadlines:{title:'Know what’s coming up',kicker:'COMPLIANCE VIEW',name:'Upcoming business filings',description:'Illustrative compliance planning workflow.',badge:'Upcoming',progress:'33%',milestones:[['✓','Review','done'],['2','Prepare','current'],['3','File',''],['4','Complete','']],bottom:'See your upcoming requirements in one place.'}};
features.forEach(b=>{b.setAttribute('aria-pressed',String(b.classList.contains('active')));b.addEventListener('click',()=>{const d=views[b.dataset.view];features.forEach(f=>{f.classList.toggle('active',f===b);f.setAttribute('aria-pressed',String(f===b));});for(const k of ['title','kicker','name','description','badge'])document.getElementById('preview-'+k).textContent=d[k];document.getElementById('preview-progress').style.width=d.progress;const steps=document.getElementById('preview-milestones');steps.replaceChildren();d.milestones.forEach(([text,label,cls],i)=>{if(i)steps.append(document.createElement('i'));const span=document.createElement('span');span.className=cls;span.textContent=text;const small=document.createElement('small');small.textContent=label;span.append(small);steps.append(span);});document.getElementById('preview-bottom').textContent=d.bottom;});});
const art=document.querySelector('.hero-art');if(art&&!matchMedia('(prefers-reduced-motion: reduce)').matches&&matchMedia('(pointer:fine)').matches){art.addEventListener('pointermove',e=>{const r=art.getBoundingClientRect();art.style.setProperty('--ry',((e.clientX-r.left)/r.width-.5)*8+'deg');art.style.setProperty('--rx',-((e.clientY-r.top)/r.height-.5)*6+'deg');});art.addEventListener('pointerleave',()=>{art.style.setProperty('--ry','0deg');art.style.setProperty('--rx','0deg');});}
const form=document.getElementById('brief-form');
if(form){const chosen=new URLSearchParams(location.search).get('service');if([...form.elements.service.options].some(o=>o.value===chosen))form.elements.service.value=chosen;let text='';form.addEventListener('submit',e=>{e.preventDefault();if(!form.reportValidity())return;const d=Object.fromEntries(new FormData(form));const service=form.elements.service.selectedOptions[0].textContent;text=`YBS SERVICE BRIEF\n\nService: ${service}\nBusiness: ${d.business.trim()}\nPrepared for: ${d.name.trim()}${d.email?'\nEmail: '+d.email.trim():''}\n\nRequirement\n${d.goal.trim()}\n\nTiming: ${d.timing.trim()||'To discuss'}\nBudget context: ${d.budget.trim()||'To discuss'}\n\nPrepared for discussion with The Y Business Services.\nScope and commercial terms to be agreed.\nybusinessservices.com`;document.getElementById('brief-text').textContent=text;form.hidden=true;const result=document.getElementById('brief-result');result.hidden=false;result.focus();});document.getElementById('edit-brief').addEventListener('click',()=>{document.getElementById('brief-result').hidden=true;form.hidden=false;form.elements.service.focus();});document.getElementById('copy-brief').addEventListener('click',async()=>{try{await navigator.clipboard.writeText(text);document.getElementById('brief-status').textContent='Brief copied. You can paste it into your YBS conversation.';}catch{document.getElementById('brief-status').textContent='Select the brief text above to copy it, or download a copy.';}});document.getElementById('download-brief').addEventListener('click',()=>{const url=URL.createObjectURL(new Blob([text],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='YBS-Service-Brief.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1500);document.getElementById('brief-status').textContent='Your brief is ready to share through your YBS account.';});}
